 if(m.drag==='tool'){m.p={x:p.x-m.offset.x,y:p.y-m.offset.y};if(m.type==='roller'){const hits=m.fur.filter(f=>f.on&&Math.abs(f.x-m.p.x)<31&&Math.abs(f.y-m.p.y)<17);if(hits.length){if(!m.used){if(!act('startRoller',{},true).ok)return;m.used=true;}const r=act('roll',{amount:hits.length},true);if(r.ok){hits.slice(0,r.removed).forEach(f=>f.on=false);tone(210,.03,'sawtooth',.008);}}}}
